// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address claimer, address receiver, uint256 amount) public {
        // Restrict inputs to avoid edge cases not relevant to the rule
        vm.assume(claimer != address(0));
        vm.assume(receiver != address(0));
        vm.assume(amount < 1e30); // reasonable bound

        // Drive the contract through claim
        (bool ok, ) = address(c).call(abi.encodeWithSignature("claim(address,uint256)", receiver, amount));

        // After claim, attempt transferOwnership to a non-zero address
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", address(1)));

        // The rule: transferOwnership to non-zero should not revert
        assertTrue(success, "transferOwnership to non-zero address should not revert after claim");
    }
}

